        <path d="M110 270 C122 286 136 296 150 300 C164 296 178 286 190 270 C204 278 214 288 222 300 C210 316 190 326 150 326 C110 326 90 316 78 300 C86 288 96 278 110 270 Z" fill="${color.base}"/>
